  // Setup Clock
  function updateClock() {
    const clockEl = document.getElementById('phoneClock');
    if (!clockEl) return;
    const now = new Date();
    const hrs = String(now.getHours()).padStart(2, '0');
    const mins = String(now.getMinutes()).padStart(2, '0');
    clockEl.textContent = `${hrs}:${mins}`;
  }
  setInterval(updateClock, 1000);
  updateClock();

  // Toast Notification Helper
  function showToast(message, icon = 'check-circle') {
    const toast = document.getElementById('toastNotification');
    const toastMsg = document.getElementById('toastMessage');
    if (!toast || !toastMsg) return;
    toastMsg.textContent = message;
    toast.classList.remove('opacity-0', 'pointer-events-none');
    toast.classList.add('opacity-100');
    setTimeout(() => {
      toast.classList.remove('opacity-100');
      toast.classList.add('opacity-0', 'pointer-events-none');
    }, 3200);
  }

  // Web Audio API Synthesizer for instant, dependency-free notification sounds
  function playNotificationSound(type = 'success') {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      if (ctx.state === 'suspended') {
        ctx.resume();
      }
      const now = ctx.currentTime;

      if (type === 'success' || type === 'accepted' || type === 'delivered') {
        // Cheerful ascending arpeggio (C5 -> E5 -> G5 -> C6)
        const notes = [523.25, 659.25, 783.99, 1046.50];
        notes.forEach((freq, idx) => {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = 'sine';
          osc.frequency.setValueAtTime(freq, now + idx * 0.09);
          gain.gain.setValueAtTime(0.18, now + idx * 0.09);
          gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.09 + 0.32);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(now + idx * 0.09);
          osc.stop(now + idx * 0.09 + 0.35);
        });
      } else if (type === 'transit' || type === 'offer') {
        // High crisp notification alert chime (E5 -> A5)
        const notes = [659.25, 880.00];
        notes.forEach((freq, idx) => {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(freq, now + idx * 0.12);
          gain.gain.setValueAtTime(0.2, now + idx * 0.12);
          gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.12 + 0.28);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(now + idx * 0.12);
          osc.stop(now + idx * 0.12 + 0.3);
        });
      } else if (type === 'declined' || type === 'rejected') {
        // Descending gentle tone (E4 -> C4)
        const notes = [329.63, 261.63];
        notes.forEach((freq, idx) => {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = 'sine';
          osc.frequency.setValueAtTime(freq, now + idx * 0.15);
          gain.gain.setValueAtTime(0.15, now + idx * 0.15);
          gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.15 + 0.3);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(now + idx * 0.15);
          osc.stop(now + idx * 0.15 + 0.35);
        });
      }
    } catch (e) {
      console.warn('Audio chime notice:', e);
    }
  }
  window.playNotificationSound = playNotificationSound;

  let statusPopupTimer = null;
  function showStatusPopup({ title, message, type = 'accepted', actionText = null, actionFn = null, icon = null }) {
    const popup = document.getElementById('statusPopupNotification');
    if (!popup) {
      showToast(message);
      return;
    }

    const card = document.getElementById('statusPopupCard');
    const iconWrapper = document.getElementById('statusPopupIconWrapper');
    const iconEl = document.getElementById('statusPopupIcon');
    const badgeEl = document.getElementById('statusPopupBadge');
    const titleEl = document.getElementById('statusPopupTitle');
    const msgEl = document.getElementById('statusPopupMessage');
    const actionRow = document.getElementById('statusPopupActionRow');
    const actionBtn = document.getElementById('statusPopupActionBtn');
    const actionTextEl = document.getElementById('statusPopupActionText');

    if (titleEl) titleEl.textContent = title;
    if (msgEl) msgEl.textContent = message;

    // Styling by type
    if (card && iconWrapper && badgeEl) {
      card.className = 'bg-white/95 backdrop-blur-md rounded-2xl shadow-2xl border-2 p-4 flex items-start gap-3 relative';
      if (type === 'accepted') {
        card.classList.add('border-emerald-500');
        iconWrapper.className = 'w-10 h-10 rounded-xl bg-emerald-100 text-emerald-700 flex items-center justify-center shrink-0';
        badgeEl.className = 'text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800';
        badgeEl.textContent = 'Deal Accepted';
        if (iconEl) iconEl.setAttribute('data-lucide', icon || 'check-circle');
      } else if (type === 'delivered') {
        card.classList.add('border-emerald-600');
        iconWrapper.className = 'w-10 h-10 rounded-xl bg-emerald-100 text-emerald-800 flex items-center justify-center shrink-0';
        badgeEl.className = 'text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-900';
        badgeEl.textContent = 'Delivered';
        if (iconEl) iconEl.setAttribute('data-lucide', icon || 'shield-check');
      } else if (type === 'transit') {
        card.classList.add('border-blue-500');
        iconWrapper.className = 'w-10 h-10 rounded-xl bg-blue-100 text-blue-700 flex items-center justify-center shrink-0';
        badgeEl.className = 'text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-blue-100 text-blue-800';
        badgeEl.textContent = 'In Transit';
        if (iconEl) iconEl.setAttribute('data-lucide', icon || 'truck');
      } else if (type === 'offer') {
        card.classList.add('border-amber-500');
        iconWrapper.className = 'w-10 h-10 rounded-xl bg-amber-100 text-amber-700 flex items-center justify-center shrink-0';
        badgeEl.className = 'text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-amber-100 text-amber-800';
        badgeEl.textContent = 'New Offer';
        if (iconEl) iconEl.setAttribute('data-lucide', icon || 'handshake');
      } else if (type === 'declined' || type === 'rejected') {
        card.classList.add('border-rose-400');
        iconWrapper.className = 'w-10 h-10 rounded-xl bg-rose-100 text-rose-700 flex items-center justify-center shrink-0';
        badgeEl.className = 'text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-rose-100 text-rose-800';
        badgeEl.textContent = 'Offer Declined';
        if (iconEl) iconEl.setAttribute('data-lucide', icon || 'x-circle');
      }
    }

    if (actionBtn && actionTextEl && actionRow) {
      if (actionText && typeof actionFn === 'function') {
        actionTextEl.textContent = actionText;
        actionRow.classList.remove('hidden');
        actionBtn.onclick = () => {
          closeStatusPopup();
          actionFn();
        };
      } else {
        actionRow.classList.add('hidden');
      }
    }

    if (window.lucide) lucide.createIcons();

    // Play synthesized chime
    playNotificationSound(type);

    // Show popup
    popup.classList.remove('-translate-y-28', 'opacity-0', 'pointer-events-none');
    popup.classList.add('translate-y-0', 'opacity-100', 'pointer-events-auto');

    // Auto dismiss after 7.5 seconds
    if (statusPopupTimer) clearTimeout(statusPopupTimer);
    statusPopupTimer = setTimeout(() => {
      closeStatusPopup();
    }, 7500);
  }
  window.showStatusPopup = showStatusPopup;

  function closeStatusPopup() {
    const popup = document.getElementById('statusPopupNotification');
    if (!popup) return;
    popup.classList.remove('translate-y-0', 'opacity-100', 'pointer-events-auto');
    popup.classList.add('-translate-y-28', 'opacity-0', 'pointer-events-none');
    if (statusPopupTimer) clearTimeout(statusPopupTimer);
  }
  window.closeStatusPopup = closeStatusPopup;

  // =========================================================================
  // AUTHENTICATION & SUPABASE INTEGRATION CONTROLLER
  // =========================================================================
  function updateSupabaseBadge(isConnected = true) {
    const badge = document.getElementById('headerSupabaseStatus');
    if (!badge) return;
    if (isConnected) {
      badge.classList.remove('hidden');
      badge.classList.add('inline-flex');
    }
  }

  function hideLoginScreen() {
    const loginScreen = document.getElementById('loginScreen');
    if (loginScreen) {
      loginScreen.style.display = 'none';
      loginScreen.classList.add('hidden');
      loginScreen.classList.remove('flex');
    }
    const oauthLoading = document.getElementById('loginOAuthLoading');
    if (oauthLoading) {
      oauthLoading.classList.add('hidden');
    }
  }

  function showLoginScreen() {
    const loginScreen = document.getElementById('loginScreen');
    if (loginScreen) {
      loginScreen.style.display = 'flex';
      loginScreen.classList.remove('hidden');
      loginScreen.classList.add('flex');
    }
    const oauthLoading = document.getElementById('loginOAuthLoading');
    if (oauthLoading) {
      oauthLoading.classList.add('hidden');
    }
  }

  // Update farmer identity across the app (drawer, profile screen, headers, wallet)
  function applyFarmerProfileUI(farmerName, email, phone, district = 'Warangal Rural', farmerId = '', walletBalance = null, creditScore = null, preApprovedLoan = null) {
    if (farmerName) {
      const drawerFarmerName = document.getElementById('drawerFarmerName');
      if (drawerFarmerName) drawerFarmerName.textContent = farmerName;
      const profileFarmerName = document.getElementById('profileFarmerName');
      if (profileFarmerName) profileFarmerName.textContent = farmerName;
    }

    const locText = (district || 'Warangal Rural') + ', Telangana';
    const drawerFarmerPlace = document.getElementById('drawerFarmerPlace');
    if (drawerFarmerPlace) drawerFarmerPlace.textContent = locText;
    const profileFarmerPlace = document.getElementById('profileFarmerPlace');
    if (profileFarmerPlace) profileFarmerPlace.textContent = locText;

    const contactText = email || (phone ? '+91 ' + phone : '');
    const profileFarmerEmail = document.getElementById('profileFarmerEmail');
    if (profileFarmerEmail && contactText) profileFarmerEmail.textContent = contactText;

    if (farmerId) {
      const profileBadgeId = document.getElementById('profileFarmerIdBadge');
      if (profileBadgeId) profileBadgeId.textContent = 'Verified Farmer (ID: ' + farmerId + ')';
    }

    if (walletBalance !== null && !isNaN(walletBalance)) {
      wallet.balance = Number(walletBalance);
      const walletEl = document.getElementById('walletTotalBalance');
      if (walletEl) walletEl.textContent = '₹' + Number(walletBalance).toLocaleString('en-IN');
    }

    if (creditScore !== null) {
      const csEl = document.getElementById('profileCreditScoreValue');
      if (csEl) csEl.textContent = creditScore;
      const drawerCsEl = document.getElementById('drawerCreditScoreBadge');
      if (drawerCsEl) drawerCsEl.textContent = 'Agri Credit Score: ' + creditScore;
    }

    if (preApprovedLoan !== null) {
      const loanEl = document.getElementById('profileLoanAmountValue');
      if (loanEl) loanEl.textContent = '₹' + Number(preApprovedLoan).toLocaleString('en-IN');
    }
  }

  // Record user login into Supabase database (profiles table + user_logins audit table)
  async function recordLoginInDatabase(farmerProfile, farmerName, provider = 'credentials') {
    if (!window.supabaseClient) return;
    try {
      console.log('📡 Recording login in Supabase database for:', farmerName, farmerProfile?.email || farmerProfile?.phone);

      // 1. Update / Record in public.profiles table
      if (farmerProfile.farmer_id) {
        await window.supabaseClient
          .from('profiles')
          .update({
            user_id: farmerProfile.user_id || null,
            updated_at: new Date().toISOString()
          })
          .eq('farmer_id', farmerProfile.farmer_id);
      }

      // 2. Insert into user_logins audit table
      try {
        await window.supabaseClient
          .from('user_logins')
          .insert([
            {
              user_id: farmerProfile.user_id || null,
              farmer_id: farmerProfile.farmer_id || null,
              email: farmerProfile.email || '',
              full_name: farmerName,
              provider: provider,
              logged_in_at: new Date().toISOString(),
              user_agent: navigator.userAgent
            }
          ]);
        console.log('✔ Successfully recorded login audit in user_logins table!');
      } catch (e) {
        // user_logins audit insert is non-blocking
      }
    } catch (e) {
      console.warn('Database login recording notice:', e.message);
    }
  }

  // Set active farmer session across storage, UI, and navigation
  async function setActiveFarmerSession(farmerProfile, provider = 'credentials') {
    const farmerId = farmerProfile.farmer_id || 'FARMER-TG-7721';
    const farmerName = farmerProfile.full_name || 'Farmer';
    const email = farmerProfile.email || '';
    const phone = farmerProfile.phone || '';
    const district = farmerProfile.district || 'Warangal Rural';
    const state = farmerProfile.state || 'Telangana';
    const walletBalance = Number(farmerProfile.wallet_balance || 25000);
    const creditScore = Number(farmerProfile.agri_credit_score || 780);
    const preApprovedLoan = Number(farmerProfile.pre_approved_loan || 250000);

    // Isolate user session: if switching farmers or new account, reset arrays
    if (currentFarmerId !== farmerId) {
      inventory = [];
      orders = [];
      negotiations = [];
      wallet.balance = walletBalance;
      wallet.transactions = [];
      localStorage.removeItem('kisan_inventory');
      localStorage.removeItem('kisan_orders');
      localStorage.removeItem('kisan_negotiations');
    }

    const localSession = {
      authenticated: true,
      role: 'farmer',
      farmerId: farmerId,
      farmerName: farmerName,
      email: email,
      phone: phone,
      district: district,
      state: state,
      walletBalance: walletBalance,
      creditScore: creditScore,
      preApprovedLoan: preApprovedLoan,
      supabaseId: farmerProfile.user_id || null,
      provider: provider,
      loginTime: new Date().toISOString()
    };

    localStorage.setItem('kisan_auth', JSON.stringify(localSession));

    // Update global references
    currentPortalRole = 'farmer';
    currentFarmerId = farmerId;
    currentFarmerName = farmerName;

    // Update UI elements
    applyFarmerProfileUI(farmerName, email, phone, district, farmerId, walletBalance, creditScore, preApprovedLoan);
    updatePortalRoleUI();
    updateSupabaseBadge(true);

    // Completely dismiss login screen and redirect to homepage
    hideLoginScreen();
    navigateTo('inventory');

    // Clean URL query and hash (remove ?code=... or #access_token=...)
    if (window.location.search.includes('code=') || window.location.hash.includes('access_token=')) {
      const cleanUrl = window.location.origin + window.location.pathname;
      window.history.replaceState({}, document.title, cleanUrl);
    }

    // Record login in database & sync user-scoped data
    await recordLoginInDatabase(farmerProfile, farmerName, provider);
    await syncWithSupabase();
  }

